package id.kemkes.satusehat;
public final class ErrorClassifier { private ErrorClassifier(){} public record Result(String category,boolean retryable){} public static Result classify(int s){if(s>=200&&s<=299)return new Result("success",false);return switch(s){case 401->new Result("unauthorized",true);case 403->new Result("forbidden",false);case 404->new Result("not_found",false);case 409->new Result("conflict",false);case 422->new Result("validation_error",false);case 429->new Result("rate_limited",true);default->{if(s>=500&&s<=599)yield new Result("server_error",true);if(s>=400&&s<=499)yield new Result("invalid_request",false);yield new Result("unexpected_http_status",false);}};}}
